"""Oracle comparison table, generated by running our code on the oracles.

For every frozen oracle file this runs the scmle function that produces the
same quantity on each case, and records the largest relative disagreement
with the reference values. An oracle with no scmle producer wired in here is
listed as such: the table says what is compared, not what is assumed. The
reference-only R oracles that are pending are listed too.

    uv run python -m benchmarks.qualification.oracle_table docs/ORACLES.md
    uv run python -m benchmarks.qualification.oracle_table --check FILE

The reported difference is a power of ten that bounds the observed maximum
(floored at 1e-14, about fifty units in the last place and six orders of
magnitude below the tightest tolerance), so a change in the last bits on
another platform or library build does not change the file. A floor at 1e-16
did not hold: the observed gaps are one to four units in the last place and two
rows are exactly zero, so a different libm moved rows across it. `--check`
exits 1 if FILE differs from a fresh run.
"""

import argparse
from collections.abc import Callable
from collections.abc import Mapping
import dataclasses
from fractions import Fraction
import math
from pathlib import Path
import sys
from typing import Any

import numpy as np

from benchmarks.qualification import oracles
from scmle.data.detectors import certificates
from scmle.data.ledger import bivariate
from scmle.data.ledger import budget
from scmle.data.ledger import multiplicity
from scmle.evaluation import coverage

FLOOR = 1e-14
Producer = Callable[[Mapping[str, Any]], Any]


@dataclasses.dataclass(frozen=True)
class Wired:
    """An scmle function compared with one oracle.

    Attributes:
        producer: Dotted name of the function under comparison.
        run: Maps a case's inputs to a value shaped like its expected.
    """

    producer: str
    run: Producer


def wilson(given: Mapping[str, Any]) -> Any:
    """Wilson interval as `{low, high}`.

    Args:
        given: Case inputs `successes`, `n` and `confidence`.

    Returns:
        The lower and upper bounds from `certificates.wilson_interval`.
    """
    low, high = certificates.wilson_interval(
        given["successes"], given["n"], given["confidence"]
    )
    return {"low": low, "high": high}


def clopper(given: Mapping[str, Any]) -> Any:
    """Clopper-Pearson interval as `{low, high}`.

    Args:
        given: Case inputs `successes`, `n` and `confidence`.

    Returns:
        The lower and upper bounds from `coverage.clopper_pearson`.
    """
    low, high = coverage.clopper_pearson(
        given["successes"], given["n"], given["confidence"]
    )
    return {"low": low, "high": high}


def spearman(given: Mapping[str, Any]) -> Any:
    """Spearman p-value and statistic.

    Args:
        given: Case inputs `x` and `y`, two equal-length numeric lists.

    Returns:
        `pvalue` and `statistic` from `bivariate.spearman`.
    """
    out = bivariate.spearman(np.array(given["x"]), np.array(given["y"]))
    return {"pvalue": out.p, "statistic": out.statistic}


def kruskal(given: Mapping[str, Any]) -> Any:
    """Kruskal-Wallis p-value and statistic.

    Args:
        given: Case input `groups`, a list of samples.

    Returns:
        `pvalue` and `statistic` from `bivariate.kruskal` on the pooled
        sample with group labels.
    """
    groups = given["groups"]
    x = np.concatenate([np.array(g) for g in groups])
    labels = np.concatenate([np.full(len(g), i) for i, g in enumerate(groups)])
    out = bivariate.kruskal(x, labels)
    return {"pvalue": out.p, "statistic": out.statistic}


def fdr(given: Mapping[str, Any]) -> Any:
    """BH or BY adjusted p-values.

    Args:
        given: Case inputs `method` (the multiplicity rule) and `pvalues`.

    Returns:
        The adjusted p-values, as a list under `adjusted`, from
        `multiplicity.adjust` at level 1/20.
    """
    rule = budget.MultiplicityRule(given["method"])
    out = multiplicity.adjust(given["pvalues"], rule, Fraction(1, 20))
    return {"adjusted": list(out.adjusted)}


def harmonic(given: Mapping[str, Any]) -> Any:
    """Harmonic number.

    Args:
        given: Case input `n`.

    Returns:
        The harmonic number under `value`.
    """
    return {"value": budget.harmonic(given["n"])}


WIRED: Mapping[str, Wired] = {
    "wilson_interval": Wired(
        "scmle.data.detectors.certificates.wilson_interval", wilson
    ),
    "clopper_pearson": Wired(
        "scmle.evaluation.coverage.clopper_pearson", clopper
    ),
    "spearmanr": Wired("scmle.data.ledger.bivariate.spearman", spearman),
    "kruskal": Wired("scmle.data.ledger.bivariate.kruskal", kruskal),
    "fdr_control": Wired("scmle.data.ledger.multiplicity.adjust", fdr),
    "harmonic_number": Wired("scmle.data.ledger.budget.harmonic", harmonic),
}


def gap(actual: Any, expected: Any) -> float:
    """Largest relative gap (absolute where the reference is zero).

    Args:
        actual: Value from our code (number, sequence or mapping).
        expected: Reference value of the same shape.

    Returns:
        The maximum over all leaves of `|a - e| / |e|`, or `|a - e|` where
        the reference is zero; 0.0 for equal values, including two NaNs.
    """
    if isinstance(expected, Mapping):
        return max(gap(actual[k], expected[k]) for k in expected)
    if isinstance(expected, list | tuple):
        return max(
            (gap(a, e) for a, e in zip(actual, expected, strict=True)),
            default=0.0,
        )
    a, e = float(actual), float(expected)
    if math.isnan(a) and math.isnan(e):
        return 0.0
    if a == e:
        return 0.0
    scale = abs(e) if e != 0.0 else 1.0
    return abs(a - e) / scale


def bound(value: float) -> str:
    """Power of ten at or above `value`, floored at `FLOOR`.

    Args:
        value: The observed maximum gap.

    Returns:
        The text `<= 1eN` for the smallest N with 10**N at least `value`,
        or `<= 1e-14` when `value` does not exceed `FLOOR`.
    """
    if value <= FLOOR:
        return f"<= {FLOOR:.0e}"
    return f"<= 1e{math.ceil(math.log10(value))}"


def rows() -> list[dict[str, Any]]:
    """One record per oracle, computed now.

    Returns:
        For each oracle name, the reference, tolerance, case count, the
        producer's dotted name and the bounded difference with whether it is
        within tolerance (both None when no producer is wired).
    """
    found = []
    for name in oracles.NAMES:
        oracle = oracles.load_oracle(name)
        wired = WIRED.get(name)
        record: dict[str, Any] = {
            "oracle": name,
            "reference": oracle.reference,
            "tolerance": oracle.tolerance["rel"],
            "cases": len(oracle.cases),
            "producer": wired.producer if wired else None,
            "difference": None,
            "within": None,
        }
        if wired:
            worst = max(
                gap(wired.run(c["inputs"]), c["expected"]) for c in oracle.cases
            )
            record["difference"] = bound(worst)
            record["within"] = worst <= oracle.tolerance["rel"]
        found.append(record)
    return found


def render() -> str:
    """The Markdown table.

    Returns:
        The full document text: a row per oracle and the list of pending
        references.
    """
    lines = [
        "# Oracle comparison",
        "",
        "Generated by `python -m benchmarks.qualification.oracle_table`; do "
        "not edit. Each row runs the scmle function named on every case of "
        "the frozen oracle file and reports a power of ten bounding the "
        "largest relative disagreement with the reference value (absolute "
        "where the reference is zero). The references are scipy outputs; "
        "agreement shows that the two computations match, not that either "
        "is correct. A row without a producer means no scmle function is "
        "compared with that oracle by this table.",
        "",
        "| Oracle | Reference | Cases | Tolerance (rel) | scmle producer | "
        "Max difference | Within |",
        "|---|---|---|---|---|---|---|",
    ]
    for r in rows():
        producer = f"`{r['producer']}`" if r["producer"] else "none wired"
        verdict = {True: "yes", False: "NO", None: "-"}[r["within"]]
        lines.append(
            f"| {r['oracle']} | `{r['reference']}` | {r['cases']} | "
            f"{r['tolerance']:.0e} | {producer} | "
            f"{r['difference'] or 'not compared'} | {verdict} |"
        )
    lines += ["", "Pending references (not produced here):", ""]
    for name, why in sorted(oracles.PENDING_R.items()):
        lines.append(f"- `{name}`: {why}")
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    """Writes the table, or with `--check` compares it with a file.

    Args:
        argv: Command-line arguments; `None` reads `sys.argv`.

    Returns:
        0 after a write or a matching check; 1 when the check finds the file
        missing or different from a fresh render.
    """
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    text = render()
    target = Path(args.path)
    if args.check:
        if not target.is_file() or target.read_text(encoding="utf-8") != text:
            print(f"{target} is missing or stale", file=sys.stderr)
            return 1
        return 0
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
